const PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>', '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdChar = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

function scan(text) {
  const s = Array.from(text)
  const n = s.length
  let i = 0
  let line = 1
  let col = 1
  const tokens = []

  const advance = () => {
    const c = s[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
  }
  const advanceN = (k) => { for (let j = 0; j < k; j++) advance() }

  // Scan a run of digits allowed by pred, with single underscores between digits.
  const run = (j, pred) => {
    while (j < n) {
      if (pred(s[j])) j++
      else if (s[j] === '_' && j > 0 && pred(s[j - 1]) && pred(s[j + 1])) j++
      else break
    }
    return j
  }

  while (i < n) {
    const c = s[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { advance(); continue }
    if (c === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') advance()
      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      const sl = line, sc = col
      advanceN(2)
      let depth = 1
      while (depth > 0) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated block comment')
        if (s[i] === '/' && s[i + 1] === '*') { depth++; advanceN(2) }
        else if (s[i] === '*' && s[i + 1] === '/') { depth--; advanceN(2) }
        else advance()
      }
      continue
    }
    const sl = line, sc = col
    if (c === 'r' && s[i + 1] === '"') {
      let j = i + 2
      while (j < n && s[j] !== '"') j++
      if (j >= n) throw new ScanError(sl, sc, 'unterminated string')
      const value = s.slice(i + 2, j).join('')
      advanceN(j + 1 - i)
      tokens.push({ line: sl, col: sc, kind: 'rawstring', body: JSON.stringify(value) })
      continue
    }
    if (isIdStart(c)) {
      let j = i
      while (j < n && isIdChar(s[j])) j++
      const word = s.slice(i, j).join('')
      advanceN(j - i)
      tokens.push({ line: sl, col: sc, kind: KEYWORDS.has(word) ? 'keyword' : 'ident', body: word })
      continue
    }
    if (isDigit(c)) {
      let j = i
      let ok = true
      const p = s[i + 1]
      if (c === '0' && p !== undefined && 'xXbBoO'.includes(p)) {
        const pred = 'xX'.includes(p) ? isHex : 'bB'.includes(p) ? isBin : isOct
        j = i + 2
        if (pred(s[j])) j = run(j, pred)
        else ok = false
      } else {
        j = run(i, isDigit)
        if (s[j] === '.' && isDigit(s[j + 1])) j = run(j + 1, isDigit)
        if (s[j] === 'e' || s[j] === 'E') {
          if (isDigit(s[j + 1])) j = run(j + 1, isDigit)
          else if ((s[j + 1] === '+' || s[j + 1] === '-') && isDigit(s[j + 2])) j = run(j + 2, isDigit)
        }
      }
      if (j < n && isIdChar(s[j])) ok = false
      if (!ok) {
        while (j < n && isIdChar(s[j])) j++
        throw new ScanError(sl, sc, `invalid number ${s.slice(i, j).join('')}`)
      }
      const word = s.slice(i, j).join('')
      advanceN(j - i)
      tokens.push({ line: sl, col: sc, kind: 'number', body: word })
      continue
    }
    if (c === '"') {
      advance()
      let value = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = s[i]
        if (d === '"') { advance(); break }
        if (d === '\n') throw new ScanError(line, col, 'newline in string')
        if (d !== '\\') { value += d; advance(); continue }
        const el = line, ec = col
        const e = s[i + 1]
        if (e === undefined) throw new ScanError(sl, sc, 'unterminated string')
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', '0': '\0' }
        if (Object.hasOwn(simple, e)) { value += simple[e]; advanceN(2); continue }
        if (e === 'x') {
          if (isHex(s[i + 2]) && isHex(s[i + 3])) {
            value += String.fromCodePoint(parseInt(s[i + 2] + s[i + 3], 16))
            advanceN(4)
            continue
          }
        } else if (e === 'u' && s[i + 2] === '{') {
          let j = i + 3
          while (isHex(s[j])) j++
          if (j > i + 3 && s[j] === '}') {
            const v = parseInt(s.slice(i + 3, j).join(''), 16)
            if (v <= 0x10ffff) {
              value += String.fromCodePoint(v)
              advanceN(j + 1 - i)
              continue
            }
          }
        }
        throw new ScanError(el, ec, `invalid escape \\${e}`)
      }
      tokens.push({ line: sl, col: sc, kind: 'string', body: JSON.stringify(value) })
      continue
    }
    const two = c + (s[i + 1] ?? '')
    const p = PUNCT.find((x) => (x.length === 2 ? x === two : x === c))
    if (p) {
      advanceN(p.length)
      tokens.push({ line: sl, col: sc, kind: 'punct', body: p })
      continue
    }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}

const mode = process.argv.length === 3 ? process.argv[2] : undefined
if (mode !== 'tokens' && mode !== 'stats') {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
let tokens
try {
  tokens = scan(readFileSync(0, 'utf8'))
} catch (err) {
  if (!(err instanceof ScanError)) throw err
  process.stderr.write(`error: ${err.line}:${err.col}: ${err.message}\n`)
  process.exit(2)
}
let out = ''
